<?php
require __DIR__.'/bootstrap.php';
require __DIR__.'/skills.php';
$route=basename($_SERVER['SCRIPT_NAME']);
if($route==='resume.php'){require __DIR__.'/resume-download.php';exit;}
$home=in_array($route,['index.php','frontpage.php']);
$signup=in_array($route,['jsignup.php','esignup.php']);
$auth=$signup || in_array($route,['jlogin.php','elogin.php']);
$employer=str_starts_with($route,'e');
$categories=query('SELECT name FROM categories ORDER BY name')->fetchAll(PDO::FETCH_COLUMN);
$error=''; $u=user();
try {
 if($_SERVER['REQUEST_METHOD']==='POST') {
  if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??''))) throw new RuntimeException('Your session expired. Refresh the page and try again.');
  $action=$_POST['action']??'';
  if($action==='signup' || $action==='login') {
   $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??'';
   if(!filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>254) throw new RuntimeException('Enter a valid email address.');
   if($action==='signup') {
    $name=trim($_POST['name']??''); if(strlen($name)<2 || strlen($name)>100 || strlen($password)<10 || strlen($password)>72) throw new RuntimeException('Use a name between 2 and 100 characters and a password between 10 and 72 characters.');
    $accountTable=$employer?'euser':'juser';
    if(query('SELECT id FROM '.$accountTable.' WHERE email=?',[$email])->fetch()) throw new RuntimeException('An account already uses this email. Please sign in.');
    db()->beginTransaction();
    query('INSERT INTO '.$accountTable.'(name,email,password,role,bio) VALUES(?,?,?,?,?)',[$name,$email,password_hash($password,PASSWORD_DEFAULT),$employer?'employer':'seeker','']);
    $id=db()->lastInsertId();
    if($employer)query('UPDATE euser SET company_name=? WHERE id=?',[$name,$id]);
    else query("INSERT INTO jprofile(user_id,bio) VALUES(?,?)",[$id,'']);
    db()->commit();
   } else {
    $ip=$_SERVER['REMOTE_ADDR']??'unknown'; $attempt=query('SELECT * FROM attempts WHERE ip=?',[$ip])->fetch();
    if($attempt && $attempt['failures']>=8 && time()-(int)$attempt['updated']<900) throw new RuntimeException('Too many sign-in attempts. Try again in 15 minutes.');
    $accountTable=$employer?'euser':'juser';
    $account=query('SELECT * FROM '.$accountTable.' WHERE email=?',[$email])->fetch();
    if(!$account || !password_verify($password,$account['password'])) {
     $otherTable=$employer?'juser':'euser';
     $otherAccount=query('SELECT * FROM '.$otherTable.' WHERE email=?',[$email])->fetch();
     if($otherAccount && password_verify($password,$otherAccount['password'])) {
      $account=$otherAccount;
      $employer=$otherTable==='euser';
     }
    }
    if(!$account || !password_verify($password,$account['password'])) {
     query('INSERT INTO attempts(ip,failures,updated) VALUES(?,1,?) ON DUPLICATE KEY UPDATE failures=CASE WHEN updated < ? THEN 1 ELSE failures+1 END, updated=?',[$ip,time(),time()-900,time()]);
     throw new RuntimeException('Email or password is incorrect.');
    }
    query('DELETE FROM attempts WHERE ip=?',[$ip]); $id=$account['id'];
   }
   session_regenerate_id(true); $_SESSION['uid']=$id; $_SESSION['role']=$employer?'employer':'seeker'; $_SESSION['csrf']=bin2hex(random_bytes(32)); go('dashboard.php');
  }
  $u=require_user();
  require __DIR__.'/profile-actions.php';
  require __DIR__.'/resume-actions.php';
  if($action==='logout'){session_destroy();go('index.php');}
  if($action==='post') {
   require_user('employer');
   $required=implode(', ',skill_list($_POST['required_skills']??''));
   if(!$required||strlen($required)>500||count(skill_list($required))>30)throw new RuntimeException('Enter 1–30 required skills, within 500 characters.');
   $title=trim($_POST['title']??''); $company=trim($_POST['company']??''); $location=trim($_POST['location']??''); $description=trim($_POST['description']??''); $category=$_POST['category']??''; $type=$_POST['type']??''; $salary=filter_var($_POST['salary']??'',FILTER_VALIDATE_INT);
   if(!$title || !$company || !$location || strlen($description)<40 || strlen($description)>15000 || strlen($title)>120 || strlen($company)>120 || strlen($location)>120 || !in_array($category,$categories,true) || !in_array($type,['Full-time','Part-time','Contract','Internship'],true) || $salary===false || $salary<0 || $salary>100000000) throw new RuntimeException('Complete every field, enter a valid annual salary, and write a description of 40–15,000 characters.');
   query('INSERT INTO eprofile(employer_id,title,company,category,location,type,salary,description,required_skills) VALUES(?,?,?,?,?,?,?,?,?)',[$u['id'],$title,$company,$category,$location,$type,$salary,$description,$required]); flash('Your job is live. Candidates can now apply.'); go('dashboard.php');
  }
  if(in_array($action,['save','apply','delete'],true)) {
   $job=query('SELECT * FROM eprofile WHERE id=?',[(int)($_POST['job_id']??0)])->fetch(); if(!$job) throw new RuntimeException('This job is no longer available.');
   if($action==='delete'){require_user('employer');query('DELETE FROM eprofile WHERE id=? AND employer_id=?',[$job['id'],$u['id']]);flash('Job removed.');go('dashboard.php');}
   require_user('seeker');
   if($action==='save') {
    if(query('SELECT * FROM saved WHERE user_id=? AND job_id=?',[$u['id'],$job['id']])->fetch()) query('DELETE FROM saved WHERE user_id=? AND job_id=?',[$u['id'],$job['id']]);
    else query('INSERT INTO saved VALUES(?,?)',[$u['id'],$job['id']]);
    flash('Saved jobs updated.');go('job.php?id='.$job['id']);
   }
   $note=trim($_POST['note']??''); if(strlen($note)<30 || strlen($note)>5000) throw new RuntimeException('Write an introduction of 30–5,000 characters.');
   $resumeId=(int)($_POST['resume_id']??0);
   if(!query('SELECT id FROM resumes WHERE id=? AND user_id=? AND is_active=1',[$resumeId,$u['id']])->fetch())throw new RuntimeException('Choose one of your uploaded résumés, or upload a PDF from your profile first.');
   query('INSERT INTO applications(job_id,user_id,note,resume_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE id=id',[$job['id'],$u['id'],$note,$resumeId]); flash('Application submitted. Track it from your dashboard.');go('dashboard.php');
  }
  if($action==='status'){require_user('employer');$status=$_POST['status']??'';if(!in_array($status,['Submitted','Shortlisted','Interview','Closed'],true))throw new RuntimeException('Choose a valid status.');query('UPDATE applications SET status=? WHERE id=? AND job_id IN (SELECT id FROM eprofile WHERE employer_id=?)',[$status,(int)$_POST['application_id'],$u['id']]);flash('Application status updated.');go('dashboard.php');}
  if($action==='profile') {
   $name=trim($_POST['name']??'');$title=trim($_POST['title']??'');$location=trim($_POST['location']??'');$bio=trim($_POST['bio']??'');
   if(strlen($name)<2 || strlen($name)>100 || strlen($title)>120 || strlen($location)>120 || strlen($bio)>3000)throw new RuntimeException('Check the profile field lengths.');
   query('UPDATE '.($u['role']==='employer'?'euser':'juser').' SET name=? WHERE id=?',[$name,$u['id']]);
   if($u['role']==='seeker')query('UPDATE jprofile SET title=?,location=?,bio=? WHERE user_id=?',[$title,$location,$bio,$u['id']]);
   else query('UPDATE euser SET title=?,location=?,bio=? WHERE id=?',[$title,$location,$bio,$u['id']]);flash('Profile updated.');go('dashboard.php');
  }
 }
} catch(RuntimeException $e){ if(db()->inTransaction())db()->rollBack(); $error=$e instanceof PDOException ? 'We could not save that change. Please try again.' : $e->getMessage(); }
$u=user();
