elect name="status" id="status-<?=h($a['id'])?>"><?php foreach(['Submitted','Shortlisted','Interview','Closed'] as $s):?><option <?= $a['status']===$s?'selected':'' ?>><?=h($s)?></option><?php endforeach;?></select><button class="button small">Update</button></form></article><?php endforeach;?>
