<?php else:
 $search=substr(trim($_GET['search']??''),0,150);$category=$_GET['category']??'';$location=substr(trim($_GET['location']??''),0,120);$type=$_GET['type']??'';$sort=$_GET['sort']??'';
 $sql='SELECT * FROM eprofile WHERE 1=1';$params=[];
 if($search!==''){$sql.=' AND (title LIKE ? OR company LIKE ? OR description LIKE ?)';array_push($params,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}
 if(in_array($category,$categories,true)){$sql.=' AND category=?';$params[]=$category;}
 if($location!==''){$sql.=' AND location LIKE ?';$params[]='%'.$location.'%';}
 if($type!==''){$sql.=' AND type=?';$params[]=$type;}
